 e={'description':desc,'properties':props,'time_seconds':times,'evidence_ids':refs,'direction_order':order,'easing':{'property':props[0],'classification':kind,'basis':basis},'status':status,'limitations':limitations or []}
 if measurement:e['easing']['measurement']=measurement
 return e
